// CBSE 10 Mathematics ch03 Pair of Linear Equations in Two Variables — practice bank with
// independent re-solve checks (Cramer's rule on the givens, ratio tests computed from coefficients).
import { Q, caseQ, child, mk, r, plot, solve2 } from '../../cbse-10-mathematics-ch01/src/lib.mjs';

/** Classify a1x + b1y = c1, a2x + b2y = c2 by the ratio test, computed independently. */
export function kind(a1, b1, c1, a2, b2, c2) {
  if (Math.abs(a1 * b2 - a2 * b1) > 1e-12) return 'unique';
  return Math.abs(a1 * c2 - a2 * c1) < 1e-12 && Math.abs(b1 * c2 - b2 * c1) < 1e-12 ? 'infinite' : 'none';
}
const sol = (...k) => solve2(...k).map((v) => Math.round(v * 1e9) / 1e9);
const eqPt = (u, v) => Math.abs(u[0] - v[0]) < 1e-9 && Math.abs(u[1] - v[1]) < 1e-9;

// ---------------------------------------------------------------- figures used by questions
const qGraph3 = plot({ x: [-1, 6], y: [-2, 6], fns: [{ expr: '5 - x', label: '$\\ell_1$' }, { expr: '2x - 1', label: '$\\ell_2$' }] }, 'Two straight lines on a grid: line l1 falls from (0, 5) to (5, 0); line l2 rises steeply through (0, minus 1). They cross at a single grid point in the first quadrant.', 'Lines $\\ell_1$ and $\\ell_2$.');
const qGraphL6 = plot({ x: [-2, 6], y: [-4, 6], fns: [{ expr: '4 - x', label: 'line 1' }, { expr: 'x - 2', label: 'line 2' }], pts: [[0, 4, '(0, 4)'], [4, 0, '(4, 0)'], [0, -2, '(0, −2)'], [2, 0, '(2, 0)']] }, 'Two lines on a grid. Line 1 passes through (0, 4) and (4, 0). Line 2 passes through (0, minus 2) and (2, 0). They cross at one point.', 'Line 1 through $(0, 4)$ and $(4, 0)$; line 2 through $(0, -2)$ and $(2, 0)$.');
const qDelivery = plot({ x: [0, 10], y: [0, 180], xl: 'distance x (km)', yl: 'charge y (₹)', fns: [{ expr: '40 + 10x', label: 'Company A' }, { expr: '20 + 15x', label: 'Company B' }], pts: [[4, 80, '(4, 80)']] }, 'Two straight lines for delivery charges against distance: company A starts at 40 rupees and rises 10 rupees per kilometre; company B starts at 20 rupees and rises 15 rupees per kilometre. They cross at (4, 80).', 'The lines cross where both companies charge the same.');

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: 'The graph of a linear equation in two variables is', opts: ['a parabola', 'a straight line', 'a circle', 'a single point'], key: 'b', sol: r`Every solution $(x, y)$ of $ax + by = c$ ($a, b$ not both $0$) lies on one straight line, and every point of that line is a solution.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => C.key('b'));
Q('m02', mk.mcq({ stem: r`Which ordered pair is a solution of $2x - 3y = 7$?`, opts: ['$(2, 1)$', '$(-2, 1)$', '$(2, -1)$', '$(1, -2)$'], key: 'c', sol: r`Substitute: $(2, -1)$ gives $4 + 3 = 7$ ✓. The others give $1$, $-7$ and $8$.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { const pts = [[2, 1], [-2, 1], [2, -1], [1, -2]]; C.which(pts.map(([x, y]) => 2 * x - 3 * y), 7); });
Q('m03', mk.mcq({ stem: r`The graphs of two linear equations are shown. The solution of the pair is`, assets: [qGraph3], opts: ['$(2, 3)$', '$(3, 2)$', '$(5, 0)$', '$(0, 5)$'], key: 'a', sol: r`The solution is the point where the lines cross: $(2, 3)$. Check with the lines' equations $x + y = 5$ and $2x - y = 1$: $2 + 3 = 5$ ✓ and $4 - 3 = 1$ ✓. Option (b) swaps the coordinates; (c) and (d) are where $\ell_1$ meets the axes.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { const p = sol(1, 1, 5, 2, -1, 1); C.assert(eqPt(p, [2, 3]), `${p}`); C.key('a'); });
Q('m04', mk.mcq({ stem: 'If the lines representing a pair of linear equations are parallel, the pair has', opts: ['a unique solution', 'no solution', 'infinitely many solutions', 'exactly two solutions'], key: 'b', sol: 'Parallel lines never meet, so there is no common point and the pair has no solution (it is inconsistent).', d: 1, c: 'recall', t: [1], time: 30 }), (C) => C.key('b'));
Q('m05', mk.mcq({ stem: r`The pair $x + 2y = 3$ and $2x + 4y = 6$ has`, opts: ['a unique solution', 'no solution', 'infinitely many solutions', 'exactly two solutions'], key: 'c', sol: r`$\dfrac{a_1}{a_2} = \dfrac12$, $\dfrac{b_1}{b_2} = \dfrac24 = \dfrac12$, $\dfrac{c_1}{c_2} = \dfrac36 = \dfrac12$. All three ratios are equal: the lines coincide, so there are infinitely many solutions.`, d: 2, c: 'understanding', t: [2], time: 45 }), (C) => C.which(['unique', 'none', 'infinite', 'two'], kind(1, 2, 3, 2, 4, 6)));
Q('m06', mk.mcq({ stem: r`The pair $3x - y = 2$ and $6x - 2y = 5$ has`, opts: ['a unique solution', 'no solution', 'infinitely many solutions', 'exactly one solution, $(1, 1)$'], key: 'b', sol: r`$\dfrac{a_1}{a_2} = \dfrac36 = \dfrac12$, $\dfrac{b_1}{b_2} = \dfrac{-1}{-2} = \dfrac12$, but $\dfrac{c_1}{c_2} = \dfrac25$. Since $\dfrac{a_1}{a_2} = \dfrac{b_1}{b_2} \ne \dfrac{c_1}{c_2}$, the lines are parallel: no solution. $(1, 1)$ satisfies the first equation only.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => C.which(['unique', 'none', 'infinite', 'unique1'], kind(3, -1, 2, 6, -2, 5)));
Q('m07', mk.mcq({ stem: r`The pair $2x + ky = 7$ and $4x + 6y = 9$ has a unique solution when`, opts: ['$k = 3$', r`$k \ne 3$`, '$k = 6$', 'for every value of $k$'], key: 'b', sol: r`Unique solution needs $\dfrac{a_1}{a_2} \ne \dfrac{b_1}{b_2}$: $\dfrac24 \ne \dfrac k6$, i.e. $k \ne 3$. For $k = 3$ the lines are parallel ($\dfrac{c_1}{c_2} = \dfrac79 \ne \dfrac12$).`, d: 2, c: 'application', t: [2], time: 60 }), (C) => { C.assert(kind(2, 3, 7, 4, 6, 9) === 'none' && [0, 1, 2, 4, 6, 10].every((k) => kind(2, k, 7, 4, 6, 9) === 'unique'), 'k = 3 only fails'); C.key('b'); });
Q('m08', mk.mcq({ stem: r`For which value of $k$ do $kx + 4y = 8$ and $9x + 12y = 24$ represent the same line?`, opts: ['$3$', '$9$', '$12$', '$4$'], key: 'a', sol: r`Coincident lines need $\dfrac k9 = \dfrac{4}{12} = \dfrac{8}{24}$. Both right-hand ratios are $\dfrac13$, so $k = 3$.`, d: 2, c: 'application', t: [2], time: 60 }), (C) => C.which([3, 9, 12, 4].map((k) => kind(k, 4, 8, 9, 12, 24) === 'infinite'), true));
Q('m09', mk.mcq({ stem: r`If $\dfrac{a_1}{a_2} \ne \dfrac{b_1}{b_2}$ for the pair $a_1x + b_1y = c_1$, $a_2x + b_2y = c_2$, the lines are`, opts: ['parallel', 'coincident', 'intersecting', 'perpendicular'], key: 'c', sol: 'Unequal ratios of the coefficients of x and y mean different slopes, so the lines intersect at exactly one point (they need not be perpendicular).', d: 1, c: 'recall', t: [2], time: 30 }), (C) => C.key('c'));
Q('m10', mk.mcq({ stem: r`The solution of $y = 2x - 1$ and $3x + y = 9$ is`, opts: ['$x = 2,\\ y = 3$', '$x = 3,\\ y = 5$', '$x = 1,\\ y = 1$', '$x = 2,\\ y = -3$'], key: 'a', sol: r`Substitute $y = 2x - 1$: $3x + 2x - 1 = 9$, so $5x = 10$, $x = 2$ and $y = 3$. **Check:** $6 + 3 = 9$ ✓. Option (b) satisfies only the first equation.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { const p = sol(-2, 1, -1, 3, 1, 9); C.which([[2, 3], [3, 5], [1, 1], [2, -3]], p); });
Q('m11', mk.mcq({ stem: r`The solution of $x + y = 14$ and $x - y = 4$ is`, opts: ['$(9, 5)$', '$(5, 9)$', '$(10, 4)$', '$(7, 7)$'], key: 'a', sol: r`Add: $2x = 18$, $x = 9$; then $y = 14 - 9 = 5$. **Check:** $9 - 5 = 4$ ✓. Option (b) swaps $x$ and $y$.`, d: 1, c: 'understanding', t: [4], time: 45 }), (C) => C.which([[9, 5], [5, 9], [10, 4], [7, 7]], sol(1, 1, 14, 1, -1, 4)));
Q('m12', mk.mcq({ stem: r`To eliminate $y$ from $3x + 4y = 10$ and $5x - 6y = 4$, a correct first step is to multiply the equations by`, opts: ['$3$ and $2$ respectively, then add', '$3$ and $2$ respectively, then subtract', '$5$ and $3$ respectively, then add', '$6$ and $4$ respectively, then subtract'], key: 'a', sol: r`$3 \times (3x + 4y) = 9x + 12y$ and $2 \times (5x - 6y) = 10x - 12y$. The $y$-terms are $+12y$ and $-12y$, so **adding** removes $y$: $19x = 38$, $x = 2$. Subtracting would give $24y$; option (c) makes the $x$-terms equal, not the $y$-terms; option (d) gives $24y - (-24y) = 48y$.`, d: 2, c: 'understanding', t: [4], time: 60 }), (C) => { const elim = ([p, q, add]) => (add ? 4 * p + -6 * q : 4 * p - -6 * q) === 0; C.which([[3, 2, true], [3, 2, false], [5, 3, true], [6, 4, false]].map(elim), true); C.sol([19, 38]); C.assert(eqPt(sol(3, 4, 10, 5, -6, 4), [2, 1]), 'x = 2'); });
Q('m13', mk.mcq({ stem: 'The sum of two numbers is 20 and their difference is 6. The numbers are', opts: ['$13$ and $7$', '$14$ and $6$', '$12$ and $8$', '$10$ and $10$'], key: 'a', sol: r`$x + y = 20$, $x - y = 6$. Adding: $2x = 26$, $x = 13$, $y = 7$. Option (b) has difference $8$.`, d: 2, c: 'application', t: [5], time: 45 }), (C) => C.which([[13, 7], [14, 6], [12, 8], [10, 10]], sol(1, 1, 20, 1, -1, 6)));
Q('m14', mk.mcq({ stem: r`If $2$ is added to both the numerator and the denominator of a fraction, it becomes $\dfrac23$. If $3$ is subtracted from both, it becomes $\dfrac12$. The fraction is`, opts: [r`$\dfrac{8}{13}$`, r`$\dfrac{13}{8}$`, r`$\dfrac{6}{11}$`, r`$\dfrac{7}{12}$`], key: 'a', sol: r`Let the fraction be $\dfrac nd$. $\dfrac{n + 2}{d + 2} = \dfrac23 \Rightarrow 3n - 2d = -2$; $\dfrac{n - 3}{d - 3} = \dfrac12 \Rightarrow 2n - d = 3$. From the second, $d = 2n - 3$; then $3n - 4n + 6 = -2$, so $n = 8$, $d = 13$. **Check:** $\dfrac{10}{15} = \dfrac23$ ✓, $\dfrac{5}{10} = \dfrac12$ ✓.`, d: 3, c: 'application', t: [5], time: 120 }), (C) => { const [n, d] = sol(3, -2, -2, 2, -1, 3); C.which([[8, 13], [13, 8], [6, 11], [7, 12]], [n, d]); C.assert((n + 2) * 3 === (d + 2) * 2 && (n - 3) * 2 === d - 3, 'conditions'); });
Q('m15', mk.mcq({ stem: "The sum of a father's and his son's ages is 50 years, and the father is 4 times as old as the son. The son's age is", opts: ['$10$ years', '$12.5$ years', '$40$ years', '$8$ years'], key: 'a', sol: r`$f + s = 50$ and $f = 4s$, so $5s = 50$ and $s = 10$ (father $40$). Option (c) is the father's age.`, d: 2, c: 'application', t: [5], time: 45 }), (C) => C.which([10, 12.5, 40, 8], sol(1, 1, 50, 1, -4, 0)[1]));
Q('m16', mk.mcq({ stem: 'A pair of linear equations is called **consistent** when it has', opts: ['no solution', 'at least one solution', 'exactly two solutions', 'only the solution (0, 0)'], key: 'b', sol: 'Consistent means at least one solution: either a unique solution (intersecting lines) or infinitely many (coincident lines). A pair with no solution is inconsistent.', d: 1, c: 'recall', t: [2], time: 30 }), (C) => C.key('b'));
Q('m17', mk.mcq({ stem: r`Substituting $y = 3 - x$ into $2x + 3y = 7$ gives`, opts: ['$x = 2$', '$x = -2$', '$x = 4$', r`$x = \dfrac{16}{5}$`], key: 'a', sol: r`$2x + 3(3 - x) = 7 \Rightarrow 2x + 9 - 3x = 7 \Rightarrow -x = -2 \Rightarrow x = 2$. Option (b) is the sign slip $-x = -2 \Rightarrow x = -2$; option (d) comes from writing $3y = 9 + 3x$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => C.which([2, -2, 4, 3.2], sol(1, 1, 3, 2, 3, 7)[0]));
Q('m18', mk.mcq({ stem: r`The solution of $37x + 43y = 123$ and $43x + 37y = 117$ is`, opts: ['$(1, 2)$', '$(2, 1)$', '$(3, 0)$', '$(-1, 4)$'], key: 'a', sol: r`**Add:** $80x + 80y = 240 \Rightarrow x + y = 3$. **Subtract** (second minus first): $6x - 6y = -6 \Rightarrow x - y = -1$. So $x = 1$, $y = 2$. **Check:** $37 + 86 = 123$ ✓, $43 + 74 = 117$ ✓. Option (b) satisfies $x + y = 3$ only.`, d: 4, c: 'analysis', t: [4], time: 120 }), (C) => C.which([[1, 2], [2, 1], [3, 0], [-1, 4]], sol(37, 43, 123, 43, 37, 117)));

// =============================================================== Assertion-reason (keys a d b c a d)
Q('ar1', mk.ar({ a: r`The pair $x + y = 4$ and $2x + 2y = 9$ has no solution.`, r: r`If $\dfrac{a_1}{a_2} = \dfrac{b_1}{b_2} \ne \dfrac{c_1}{c_2}$, the lines are parallel.`, key: 'a', sol: r`Ratios: $\dfrac12 = \dfrac12 \ne \dfrac49$. By R the lines are parallel, so they never meet and there is no solution. R explains A.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(kind(1, 1, 4, 2, 2, 9) === 'none', 'none'); C.key('a'); });
Q('ar2', mk.ar({ a: r`The pair $2x + 3y = 6$ and $4x + 6y = 12$ has a unique solution.`, r: 'If all three ratios of corresponding coefficients are equal, the two lines coincide.', key: 'd', sol: r`All three ratios are $\dfrac12$, so by R the lines coincide and there are **infinitely many** solutions. A is false; R is true.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(kind(2, 3, 6, 4, 6, 12) === 'infinite', 'infinite'); C.key('d'); });
Q('ar3', mk.ar({ a: r`$x = 2,\ y = 1$ is a solution of both $3x - 2y = 4$ and $x + y = 3$.`, r: 'Two intersecting lines have exactly one point in common.', key: 'b', sol: r`A: $6 - 2 = 4$ ✓ and $2 + 1 = 3$ ✓, so A is true. R is true. But A is shown by substitution; R only says there is one common point, not which point. R does not explain A.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(eqPt(sol(3, -2, 4, 1, 1, 3), [2, 1]), 'solution'); C.key('b'); });
Q('ar4', mk.ar({ a: r`The pair $x - 2y = 0$ and $3x + 4y = 20$ is consistent.`, r: 'A pair of linear equations is consistent only when its lines coincide.', key: 'c', sol: r`$\dfrac13 \ne \dfrac{-2}{4}$, so the lines intersect: a unique solution ($x = 4$, $y = 2$), hence consistent. A is true. R is false: intersecting lines also give a consistent pair.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(kind(1, -2, 0, 3, 4, 20) === 'unique' && eqPt(sol(1, -2, 0, 3, 4, 20), [4, 2]), 'unique (4, 2)'); C.key('c'); });
Q('ar5', mk.ar({ a: r`Solving $2x + 3y = 8$ and $4x + 6y = 7$ by elimination leads to $0 = 9$, so the pair has no solution.`, r: r`If correct steps lead to a false statement such as $0 = 9$, the pair has no solution.`, key: 'a', sol: r`Double the first: $4x + 6y = 16$. Subtract the second: the left side becomes $0$ and the right side $9$, and $0 \ne 9$ is false. Since the steps were correct, no $(x, y)$ satisfies both: R is exactly the reason.`, d: 3, c: 'application', t: [4] }), (C) => { C.assert(kind(2, 3, 8, 4, 6, 7) === 'none' && 2 * 8 - 7 === 9, '0 = 9'); C.key('a'); });
Q('ar6', mk.ar({ a: 'If the sum of two numbers is 12 and their difference is 4, the numbers are 7 and 5.', r: r`The pair $x + y = 12$, $x - y = 4$ gives $x = 8$.`, key: 'd', sol: r`Adding gives $2x = 16$, $x = 8$, $y = 4$ (R is true). $7$ and $5$ have sum $12$ but difference $2$, so A is false.`, d: 2, c: 'application', t: [5] }), (C) => { C.assert(eqPt(sol(1, 1, 12, 1, -1, 4), [8, 4]), '8, 4'); C.key('d'); });

// =============================================================== True / false
Q('tf1', mk.tf({ stem: 'A single linear equation in two variables has infinitely many solutions.', key: 't', sol: r`For every value of $x$ there is a matching $y$; every point on its line is a solution.`, d: 1, c: 'recall', t: [1] }), (C) => C.key('t'));
Q('tf2', mk.tf({ stem: r`The lines $x = 3$ and $y = 2$ intersect at the point $(3, 2)$.`, key: 't', sol: r`$x = 3$ is a vertical line and $y = 2$ a horizontal line; the only point on both has $x = 3$ and $y = 2$.`, d: 1, c: 'understanding', t: [1] }), (C) => C.key('t'));
Q('tf3', mk.tf({ stem: 'If a pair of linear equations is inconsistent, its lines intersect at exactly one point.', key: 'f', sol: 'Inconsistent means no solution: the lines are parallel and never meet.', d: 1, c: 'recall', t: [2] }), (C) => C.key('f'));
Q('tf4', mk.tf({ stem: r`If elimination leads to the true statement $0 = 0$, the pair has no solution.`, key: 'f', sol: r`$0 = 0$ means one equation is a multiple of the other: the lines coincide and there are **infinitely many** solutions. A false statement (left side $0$, right side non-zero, e.g. $0 \ne 5$) means no solution.`, d: 2, c: 'understanding', t: [4] }), (C) => C.key('f'));
Q('tf5', mk.tf({ stem: r`The pair $y = 2x$ and $y = 2x + 3$ has no solution.`, key: 't', sol: r`Both lines have slope $2$ but different $y$-intercepts ($0$ and $3$), so they are parallel. Equivalently $2x = 2x + 3$ would need $0$ to equal $3$, which is impossible.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(kind(-2, 1, 0, -2, 1, 3) === 'none', 'none'); C.key('t'); });

// =============================================================== Fill in the blank
Q('fb1', mk.fill({ stem: r`The pair $a_1x + b_1y = c_1$, $a_2x + b_2y = c_2$ has a unique solution when $\dfrac{a_1}{a_2}$ is ___ $\dfrac{b_1}{b_2}$.`, acc: [['not equal to', '≠', 'unequal to', 'different from']], sol: r`Unique solution: $\dfrac{a_1}{a_2} \ne \dfrac{b_1}{b_2}$ (intersecting lines).`, d: 1, c: 'recall', t: [2] }), (C) => C.blank('not equal to'));
Q('fb2', mk.fill({ stem: r`The pair $4x - 6y = 10$ and $2x - 3y = 5$ has ___ solutions.`, acc: [['infinitely many', 'infinite', 'infinitely']], sol: r`All ratios equal $2$: $\dfrac42 = \dfrac{-6}{-3} = \dfrac{10}{5}$. The lines coincide.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(kind(4, -6, 10, 2, -3, 5) === 'infinite', 'coincident'); C.blank('infinitely many'); });
Q('fb3', mk.fill({ stem: r`If $x = 2y$ and $x + y = 9$, then $y =$ ___.`, acc: [['3']], sol: r`Substitute: $2y + y = 9$, $y = 3$ (and $x = 6$).`, d: 1, c: 'understanding', t: [3] }), (C) => C.blank(sol(1, -2, 0, 1, 1, 9)[1]));
Q('fb4', mk.fill({ stem: r`If $x + y = 10$ and $x - y = 2$, then $x =$ ___.`, acc: [['6']], sol: r`Add: $2x = 12$, $x = 6$ (and $y = 4$).`, d: 1, c: 'understanding', t: [4] }), (C) => C.blank(sol(1, 1, 10, 1, -1, 2)[0]));
Q('fb5', mk.fill({ stem: r`The value of $k$ for which $3x + ky = 9$ and $6x + 4y = 18$ have infinitely many solutions is ___.`, acc: [['2']], sol: r`$\dfrac36 = \dfrac k4 = \dfrac{9}{18}$, all equal to $\dfrac12$, so $k = 2$.`, d: 2, c: 'application', t: [2] }), (C) => { const k = [1, 2, 3, 4, 6].find((k0) => kind(3, k0, 9, 6, 4, 18) === 'infinite'); C.blank(k); });

// =============================================================== Numerical
Q('n01', mk.num({ stem: r`Solve $5x + 2y = 16$ and $3x - 2y = 0$. Find the value of $y$.`, value: 3, marks: 2, sol: r`**Step 1.** Add: $8x = 16$, so $x = 2$. **Step 2.** $3(2) - 2y = 0 \Rightarrow y = 3$. **Check:** $10 + 6 = 16$ ✓.`, scheme: [['x = 2 by elimination', 1], ['y = 3', 1]], d: 2, c: 'understanding', t: [4], time: 90 }), (C) => C.val(sol(5, 2, 16, 3, -2, 0)[1]));
Q('n02', mk.num({ stem: r`Solve by substitution: $x = 3y - 5$ and $2x + y = 11$. Find $x$.`, value: 4, marks: 2, sol: r`**Step 1.** $2(3y - 5) + y = 11 \Rightarrow 7y = 21 \Rightarrow y = 3$. **Step 2.** $x = 9 - 5 = 4$. **Check:** $8 + 3 = 11$ ✓.`, scheme: [['y = 3', 1], ['x = 4', 1]], d: 2, c: 'understanding', t: [3], time: 90 }), (C) => C.val(sol(1, -3, -5, 2, 1, 11)[0]));
Q('n03', mk.num({ stem: r`Find the value of $k$ for which the pair $3x + ky = 7$ and $9x + 12y = 14$ has no solution.`, value: 4, marks: 2, sol: r`**Step 1.** No solution needs $\dfrac39 = \dfrac{k}{12} \ne \dfrac{7}{14}$. **Step 2.** $\dfrac k{12} = \dfrac13 \Rightarrow k = 4$; and $\dfrac{7}{14} = \dfrac12 \ne \dfrac13$ ✓.`, scheme: [['Correct condition a₁/a₂ = b₁/b₂ ≠ c₁/c₂', 1], ['k = 4 with the third ratio checked', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { const k = [1, 2, 3, 4, 6, 12].find((k0) => kind(3, k0, 7, 9, 12, 14) === 'none'); C.val(k); });
Q('n04', mk.num({ stem: r`At a stationery shop in Patna, $4$ pens and $3$ notebooks cost ₹$190$, while $2$ pens and $5$ notebooks cost ₹$270$. Find the cost of one notebook in rupees.`, value: 50, unit: '₹', marks: 2, sol: r`**Step 1.** $4p + 3n = 190$ and $2p + 5n = 270$. **Step 2.** Double the second: $4p + 10n = 540$; subtract the first: $7n = 350$, $n = 50$. **Step 3.** $4p = 190 - 150 = 40$, $p = 10$. **Check:** $20 + 250 = 270$ ✓.`, scheme: [['Correct pair of equations', 1], ['Notebook ₹50', 1]], d: 2, c: 'application', t: [5], time: 150 }), (C) => { const [p, n] = sol(4, 3, 190, 2, 5, 270); C.val(n); C.sol([p, 540, 350]); });
Q('n05', mk.num({ stem: 'The sum of the ages of Ravi and his sister is 30 years. Six years ago, Ravi was twice as old as his sister. Find Ravi\'s present age in years.', value: 18, unit: 'years', marks: 2, sol: r`**Step 1.** $r + s = 30$ and $r - 6 = 2(s - 6)$, i.e. $r - 2s = -6$. **Step 2.** Subtract: $3s = 36$, $s = 12$, $r = 18$. **Check:** six years ago $12 = 2 \times 6$ ✓.`, scheme: [['Both equations', 1], ['Ravi 18 years', 1]], d: 2, c: 'application', t: [5], time: 150 }), (C) => { const [rv, s] = sol(1, 1, 30, 1, -2, -6); C.val(rv); C.sol([s]); });
Q('n06', mk.num({ stem: 'The sum of the digits of a two-digit number is 11. If 45 is added to the number, the digits are reversed. Find the number.', value: 38, marks: 2, sol: r`**Step 1.** Let the tens digit be $t$ and the units digit $u$: $t + u = 11$ and $10t + u + 45 = 10u + t$, i.e. $u - t = 5$. **Step 2.** Adding: $2u = 16$, $u = 8$, $t = 3$. The number is $38$. **Check:** $38 + 45 = 83$ ✓.`, scheme: [['Equations t + u = 11 and u − t = 5', 1], ['Number 38', 1]], d: 3, c: 'application', t: [5], time: 150 }), (C) => { const [t, u] = sol(1, 1, 11, -1, 1, 5); C.val(10 * t + u); C.assert(10 * t + u + 45 === 10 * u + t, 'reversal'); });
Q('n07', mk.num({ stem: r`Mr. Iyer invests ₹$30000$ in two schemes, part at $5\%$ and the rest at $7\%$ simple interest per year. His total interest for one year is ₹$1800$. How much (in ₹) did he invest at $7\%$?`, value: 15000, unit: '₹', marks: 2, sol: r`**Step 1.** $x + y = 30000$ and $0.05x + 0.07y = 1800$, i.e. $5x + 7y = 180000$. **Step 2.** $5x + 5y = 150000$; subtract: $2y = 30000$, $y = 15000$. **Check:** $750 + 1050 = 1800$ ✓.`, scheme: [['Both equations', 1], ['₹15000 at 7%', 1]], d: 3, c: 'application', t: [5], time: 150 }), (C) => { const [x, y] = sol(1, 1, 30000, 5, 7, 180000); C.val(y); C.assert(0.05 * x + 0.07 * y === 1800, 'interest'); });
Q('n08', mk.num({ stem: r`Find the area (in square units) of the triangle formed by the lines $2x + y = 6$, $x - y = 0$ and the $x$-axis.`, value: 3, marks: 2, sol: r`**Step 1.** Intersection of the lines: $2x + x = 6$, so $(2, 2)$. **Step 2.** $2x + y = 6$ meets the $x$-axis at $(3, 0)$ and $x - y = 0$ at $(0, 0)$. **Step 3.** Base $3$, height $2$: area $= \dfrac12 \times 3 \times 2 = 3$ square units.`, scheme: [['Vertices (2, 2), (3, 0), (0, 0)', 1], ['Area 3', 1]], d: 3, c: 'analysis', t: [1], time: 180 }), (C) => { const P = sol(2, 1, 6, 1, -1, 0); C.assert(eqPt(P, [2, 2]), 'apex'); C.val(0.5 * 3 * P[1]); });
Q('n09', mk.num({ stem: r`If $2x + 3y = 13$ and $3x + 2y = 12$, find $x + y$.`, value: 5, sol: r`Add the equations: $5x + 5y = 25$, so $x + y = 5$. (No need to find $x$ and $y$ separately; they are $2$ and $3$.)`, scheme: [['x + y = 5', 1]], d: 2, c: 'application', t: [4], time: 60 }), (C) => { const [x, y] = sol(2, 3, 13, 3, 2, 12); C.val(x + y); });

// =============================================================== Short answer, 2 marks
Q('s201', mk.short({ marks: 2, stem: r`Without solving, decide whether the pair $x + 3y = 6$ and $2x - 3y = 12$ is consistent. Justify.`, model: r`$\dfrac{a_1}{a_2} = \dfrac12$ and $\dfrac{b_1}{b_2} = \dfrac{3}{-3} = -1$. Since $\dfrac{a_1}{a_2} \ne \dfrac{b_1}{b_2}$, the lines intersect in exactly one point: a unique solution, so the pair is **consistent**.`, sol: r`(Its solution is $x = 6$, $y = 0$.)`, scheme: [['Both ratios computed', 1], ['Unequal ⇒ unique solution ⇒ consistent', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(kind(1, 3, 6, 2, -3, 12) === 'unique' && eqPt(sol(1, 3, 6, 2, -3, 12), [6, 0]), 'unique (6, 0)'); C.model(['consistent']); C.sol([6, 0]); });
Q('s202', mk.short({ marks: 2, stem: r`Solve by substitution: $2x + y = 7$ and $3x - 2y = 0$.`, model: r`From the first, $y = 7 - 2x$. Then $3x - 2(7 - 2x) = 0 \Rightarrow 7x = 14 \Rightarrow x = 2$, and $y = 7 - 4 = 3$.

Check: $3(2) - 2(3) = 0$ ✓.`, sol: r`Isolate $y$ from the equation where its coefficient is $1$.`, scheme: [['Substitution and x = 2', 1], ['y = 3', 1]], d: 2, c: 'understanding', t: [3], time: 120 }), (C) => { C.assert(eqPt(sol(2, 1, 7, 3, -2, 0), [2, 3]), 'sol'); C.model([2, 3, 14]); });
Q('s203', mk.short({ marks: 2, stem: r`Solve by elimination: $3x + 2y = 11$ and $2x + 3y = 4$.`, model: r`Multiply by $3$ and $2$: $9x + 6y = 33$ and $4x + 6y = 8$. Subtract: $5x = 25$, $x = 5$. Then $2y = 11 - 15 = -4$, $y = -2$.

Check: $10 - 6 = 4$ ✓.`, sol: r`Make the $y$-coefficients equal ($6y$), then subtract.`, scheme: [['Equal coefficients and x = 5', 1], ['y = −2', 1]], d: 2, c: 'understanding', t: [4], time: 120 }), (C) => { C.assert(eqPt(sol(3, 2, 11, 2, 3, 4), [5, -2]), 'sol'); C.model([33, 8, 25, 5, -2]); });
Q('s204', mk.short({ marks: 2, stem: r`Find $k$ for which the pair $(k + 1)x + 2y = 6$ and $6x + 4y = 12$ has infinitely many solutions.`, model: r`Infinitely many solutions need $\dfrac{k + 1}{6} = \dfrac24 = \dfrac{6}{12}$. The last two ratios are both $\dfrac12$, so $k + 1 = 3$ and $k = 2$.`, sol: r`With $k = 2$: $3x + 2y = 6$ is exactly half of $6x + 4y = 12$.`, scheme: [['Condition with all three ratios', 1], ['k = 2', 1]], d: 2, c: 'application', t: [2], time: 120 }), (C) => { C.assert(kind(3, 2, 6, 6, 4, 12) === 'infinite' && kind(2, 2, 6, 6, 4, 12) !== 'infinite', 'k = 2'); C.model([2]); });
Q('s205', mk.short({ marks: 2, stem: r`Check whether the point $(1, 4)$ lies on both lines $3x + y = 7$ and $x - y = -3$. What does your answer mean for the graphs?`, model: r`$3(1) + 4 = 7$ ✓ and $1 - 4 = -3$ ✓. So $(1, 4)$ lies on both lines. Since the ratios $\dfrac31 \ne \dfrac{1}{-1}$, the lines intersect at only one point, so $(1, 4)$ is **the** point of intersection: the unique solution of the pair.`, sol: 'Substitute into both equations.', scheme: [['Both substitutions correct', 1], ['Interprets as the intersection / unique solution', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => { C.assert(eqPt(sol(3, 1, 7, 1, -1, -3), [1, 4]), '(1, 4)'); C.model(['(1, 4)']); });
Q('s206', mk.short({ marks: 2, stem: 'Two numbers differ by 8, and the larger is three times the smaller. Form a pair of equations and find the numbers.', model: r`Let the numbers be $x$ (larger) and $y$. $x - y = 8$ and $x = 3y$. Then $3y - y = 8$, $y = 4$, $x = 12$. The numbers are $12$ and $4$.`, sol: 'Substitute x = 3y.', scheme: [['Both equations', 1], ['12 and 4', 1]], d: 2, c: 'application', t: [5], time: 90 }), (C) => { C.assert(eqPt(sol(1, -1, 8, 1, -3, 0), [12, 4]), 'sol'); C.model([12, 4]); });
Q('s207', mk.short({ marks: 2, stem: r`Kiran solves $2x + 5y = 1$ and $3x + 2y = 7$. She writes:

*Multiply by 3 and 2: $6x + 15y = 3$ and $6x + 4y = 14$. Subtract: $11y = 11$, so $y = 1$ and $x = -2$.*

Find her mistake and give the correct solution.`, model: r`Subtracting gives $11y = 3 - 14 = -11$, not $11$. So $y = -1$, and $2x - 5 = 1$ gives $x = 3$.

Check: $3(3) + 2(-1) = 7$ ✓. (Her answer fails: $3(-2) + 2(1) = -4 \ne 7$.)`, sol: 'The right-hand sides must be subtracted in the same order as the left-hand sides.', scheme: [['Identifies the sign error 3 − 14 = −11', 1], ['Correct x = 3, y = −1', 1]], d: 3, c: 'evaluation', t: [4], time: 150 }), (C) => { C.assert(eqPt(sol(2, 5, 1, 3, 2, 7), [3, -1]) && 3 * -2 + 2 * 1 === -4, 'correct and wrong'); C.model([-11, -1, 3]); });
Q('s208', mk.short({ marks: 2, stem: r`Show that the pair $3x - 5y = 4$ and $9x - 15y = 10$ has no solution, and say what this means for the graphs.`, model: r`$\dfrac{a_1}{a_2} = \dfrac39 = \dfrac13$, $\dfrac{b_1}{b_2} = \dfrac{-5}{-15} = \dfrac13$, $\dfrac{c_1}{c_2} = \dfrac{4}{10} = \dfrac25$. As $\dfrac{a_1}{a_2} = \dfrac{b_1}{b_2} \ne \dfrac{c_1}{c_2}$, there is no solution: the lines are **parallel** (inconsistent pair).`, sol: 'Ratio test.', scheme: [['Three ratios', 1], ['Conclusion: no solution, parallel lines', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(kind(3, -5, 4, 9, -15, 10) === 'none', 'none'); C.model(['parallel']); });
Q('s209', mk.short({ marks: 2, stem: r`Anjali has only ₹$10$ and ₹$20$ notes in her wallet: $25$ notes worth ₹$380$ in all. How many notes of each kind does she have?`, model: r`Let $x$ = number of ₹$10$ notes and $y$ = number of ₹$20$ notes. $x + y = 25$ and $10x + 20y = 380$, i.e. $x + 2y = 38$. Subtract: $y = 13$, so $x = 12$.

She has $12$ notes of ₹$10$ and $13$ notes of ₹$20$. Check: $120 + 260 = 380$ ✓.`, sol: 'Count equation and value equation.', scheme: [['Both equations', 1], ['12 and 13 notes', 1]], d: 2, c: 'application', t: [5], time: 120 }), (C) => { const [x, y] = sol(1, 1, 25, 10, 20, 380); C.model([x, y]); });

// =============================================================== Short answer, 3 marks
Q('s301', mk.short({ marks: 3, stem: r`Solve by substitution: $\dfrac{x}{2} + \dfrac{y}{3} = 6$ and $\dfrac{x}{3} - \dfrac{y}{4} = \dfrac{7}{6}$.`, model: r`Clear fractions: multiply the first by $6$: $3x + 2y = 36$; multiply the second by $12$: $4x - 3y = 14$.

From the first, $y = \dfrac{36 - 3x}{2}$. Substitute: $4x - \dfrac{3(36 - 3x)}{2} = 14 \Rightarrow 8x - 108 + 9x = 28 \Rightarrow 17x = 136 \Rightarrow x = 8$.

Then $y = \dfrac{36 - 24}{2} = 6$. Check: $\dfrac82 + \dfrac63 = 6$ ✓ and $\dfrac83 - \dfrac64 = \dfrac{7}{6}$ ✓.`, sol: r`Clearing denominators first keeps the arithmetic simple.`, scheme: [['Both equations without fractions', 1], ['Substitution leading to x = 8', 1], ['y = 6 with check', 1]], d: 3, c: 'application', t: [3], time: 270 }), (C) => { const p = sol(3, 2, 36, 4, -3, 14); C.assert(eqPt(p, [8, 6]) && Math.abs(8 / 3 - 6 / 4 - 7 / 6) < 1e-12, 'sol'); C.model([36, 14, 136, 8, 6]); });
Q('s302', mk.short({ marks: 3, stem: r`Solve by elimination: $5x - 3y = 19$ and $3x + 4y = -6$.`, model: r`Multiply the first by $4$ and the second by $3$: $20x - 12y = 76$ and $9x + 12y = -18$.

Add: $29x = 58$, so $x = 2$. Then $3y = 5(2) - 19 = -9$, $y = -3$.

Check: $3(2) + 4(-3) = -6$ ✓.`, sol: 'Equal and opposite y-coefficients, then add.', scheme: [['Multipliers 4 and 3', 1], ['x = 2', 1], ['y = −3 with check', 1]], d: 2, c: 'understanding', t: [4], time: 240 }), (C) => { C.assert(eqPt(sol(5, -3, 19, 3, 4, -6), [2, -3]), 'sol'); C.model([76, -18, 58, 2, -3]); });
Q('s303', mk.short({ marks: 3, stem: r`Find $a$ and $b$ for which the pair $2x + 3y = 7$ and $(a + b)x + (2a - b)y = 21$ has infinitely many solutions.`, model: r`Infinitely many solutions need $\dfrac{a + b}{2} = \dfrac{2a - b}{3} = \dfrac{21}{7} = 3$.

So $a + b = 6$ and $2a - b = 9$. Adding: $3a = 15$, $a = 5$, and $b = 1$.

Check: the second equation becomes $6x + 9y = 21$, which is $3 \times (2x + 3y = 7)$ ✓.`, sol: 'Set each of the first two ratios equal to the known third ratio.', scheme: [['Condition with ratio 3', 1], ['a + b = 6 and 2a − b = 9', 1], ['a = 5, b = 1', 1]], d: 4, c: 'analysis', t: [2], time: 300 }), (C) => { const [a, b] = sol(1, 1, 6, 2, -1, 9); C.assert(kind(2, 3, 7, a + b, 2 * a - b, 21) === 'infinite', 'coincident'); C.model([a, b]); });
Q('s304', mk.short({ marks: 3, stem: r`A tea merchant in Guwahati blends two varieties costing ₹$400$ per kg and ₹$600$ per kg to make $20$ kg of a blend worth ₹$450$ per kg. How many kilograms of each variety does he use?`, model: r`Let $x$ kg at ₹$400$ and $y$ kg at ₹$600$. Then $x + y = 20$ and $400x + 600y = 450 \times 20 = 9000$, i.e. $2x + 3y = 45$.

From $x = 20 - y$: $40 - 2y + 3y = 45$, so $y = 5$ and $x = 15$.

He uses $15$ kg of the ₹$400$ tea and $5$ kg of the ₹$600$ tea. Check: $6000 + 3000 = 9000$ ✓.`, sol: 'Quantity equation and value equation.', scheme: [['Both equations', 1], ['Solving', 1], ['15 kg and 5 kg', 1]], d: 3, c: 'application', t: [5], time: 270 }), (C) => { const [x, y] = sol(1, 1, 20, 400, 600, 9000); C.model([x, y, 9000]); });
Q('s305', mk.short({ marks: 3, stem: r`In $\triangle ABC$, $\angle A = (x + 15)^\circ$, $\angle B = (2y)^\circ$ and $\angle C = (x + y + 20)^\circ$. If $\angle A = \angle B$, find $x$, $y$ and all three angles.`, model: r`$\angle A = \angle B$: $x + 15 = 2y$, i.e. $x - 2y = -15$.

Angle sum: $(x + 15) + 2y + (x + y + 20) = 180$, i.e. $2x + 3y = 145$.

From the first, $x = 2y - 15$: $4y - 30 + 3y = 145$, so $y = 25$ and $x = 35$.

Angles: $\angle A = 50^\circ$, $\angle B = 50^\circ$, $\angle C = 80^\circ$ (sum $180^\circ$ ✓).`, sol: 'Two conditions give two equations.', scheme: [['Two equations', 1], ['x = 35, y = 25', 1], ['Angles 50°, 50°, 80°', 1]], d: 3, c: 'application', t: [5], time: 270 }), (C) => { const [x, y] = sol(1, -2, -15, 2, 3, 145); C.assert(x + 15 === 50 && 2 * y === 50 && x + y + 20 === 80, 'angles'); C.model([x, y, '50^\\circ', '80^\\circ']); });
Q('s306', mk.short({ marks: 3, stem: 'Twelve years from now, a man will be twice as old as his son. Eight years ago, he was six times as old as his son. Find their present ages.', model: r`Let the man be $m$ and the son $s$ years old.

$m + 12 = 2(s + 12) \Rightarrow m - 2s = 12$, and $m - 8 = 6(s - 8) \Rightarrow m - 6s = -40$.

Subtract: $4s = 52$, $s = 13$; then $m = 38$.

Check: in twelve years $50 = 2 \times 25$ ✓; eight years ago $30 = 6 \times 5$ ✓.`, sol: 'Shift both ages by the same number of years.', scheme: [['Both equations', 1], ['Son 13 years', 1], ['Man 38 years with check', 1]], d: 3, c: 'application', t: [5], time: 270 }), (C) => { const [m, s] = sol(1, -2, 12, 1, -6, -40); C.model([m, s, 50, 30]); });
Q('s307', mk.short({ marks: 3, stem: r`Without drawing, decide which of these pairs are consistent, giving the reason: (a) $x - 4y = 5$, $3x - 12y = 15$; (b) $2x + y = 6$, $4x + 2y = 9$; (c) $x + y = 2$, $x - y = 8$.`, model: r`(a) $\dfrac13 = \dfrac{-4}{-12} = \dfrac{5}{15}$: coincident lines, infinitely many solutions — **consistent**.

(b) $\dfrac24 = \dfrac12 \ne \dfrac69$: parallel lines, no solution — **inconsistent**.

(c) $\dfrac11 \ne \dfrac{1}{-1}$: intersecting lines, unique solution $(5, -3)$ — **consistent**.`, sol: 'Compare the three ratios for each pair.', scheme: [['(a) consistent (dependent)', 1], ['(b) inconsistent', 1], ['(c) consistent, unique', 1]], d: 2, c: 'understanding', t: [2], time: 240 }), (C) => { C.assert(kind(1, -4, 5, 3, -12, 15) === 'infinite' && kind(2, 1, 6, 4, 2, 9) === 'none' && kind(1, 1, 2, 1, -1, 8) === 'unique' && eqPt(sol(1, 1, 2, 1, -1, 8), [5, -3]), 'classes'); C.model(['(5, -3)']); });

// =============================================================== Long answer, 5 marks
Q('l01', mk.long({ stem: r`Solve graphically: $2x + y = 8$ and $x - y = 1$. Also find the coordinates of the vertices of the triangle formed by these two lines and the $y$-axis, and its area.`, model: r`Tables of values:

| $2x + y = 8$ | $x$ | $0$ | $2$ | $4$ |
|---|---|---|---|---|
| | $y$ | $8$ | $4$ | $0$ |

| $x - y = 1$ | $x$ | $0$ | $1$ | $3$ |
|---|---|---|---|---|
| | $y$ | $-1$ | $0$ | $2$ |

Plotting and joining gives two lines that meet at $(3, 2)$. Solution: $x = 3$, $y = 2$.

The lines meet the $y$-axis at $(0, 8)$ and $(0, -1)$. Vertices of the triangle: $(0, 8)$, $(0, -1)$, $(3, 2)$.

Area $= \dfrac12 \times \text{base on the } y\text{-axis} \times \text{height} = \dfrac12 \times 9 \times 3 = 13.5$ square units.`, sol: r`Check: $6 + 2 = 8$ ✓ and $3 - 2 = 1$ ✓. The base is the segment of the $y$-axis from $-1$ to $8$, length $9$; the height is the distance of $(3, 2)$ from the $y$-axis, $3$.`, scheme: [['Two correct tables of values', 1], ['Both lines drawn correctly', 1], ['Solution (3, 2) read from the graph', 1], ['Vertices (0, 8), (0, −1), (3, 2)', 1], ['Area 13.5 square units', 1]], d: 3, c: 'application', t: [1], time: 660 }), (C) => { const p = sol(2, 1, 8, 1, -1, 1); C.assert(eqPt(p, [3, 2]), 'intersection'); C.model([3, 2, 8, -1, 0.5 * 9 * 3]); });
Q('l02', mk.long({ stem: r`Solve the pair $3x - 4y = 10$ and $2x + 3y = 1$ (a) by elimination and (b) by substitution. Verify your answer.`, model: r`**(a) Elimination.** Multiply by $3$ and $4$: $9x - 12y = 30$ and $8x + 12y = 4$. Add: $17x = 34$, $x = 2$. Then $4y = 3(2) - 10 = -4$, $y = -1$.

**(b) Substitution.** From the second, $x = \dfrac{1 - 3y}{2}$. Then $3 \cdot \dfrac{1 - 3y}{2} - 4y = 10 \Rightarrow 3 - 9y - 8y = 20 \Rightarrow -17y = 17 \Rightarrow y = -1$, and $x = \dfrac{1 + 3}{2} = 2$.

**Verification:** $3(2) - 4(-1) = 10$ ✓ and $2(2) + 3(-1) = 1$ ✓.`, sol: 'Both methods must give the same unique solution, since the ratios 3/2 and −4/3 differ.', scheme: [['Elimination: equal coefficients', 1], ['Elimination: x = 2, y = −1', 1], ['Substitution set-up', 1], ['Substitution: y = −1, x = 2', 1], ['Verification in both equations', 1]], d: 2, c: 'understanding', t: [3, 4], time: 600 }), (C) => { C.assert(eqPt(sol(3, -4, 10, 2, 3, 1), [2, -1]), 'sol'); C.model([30, 4, 34, 2, -1, 17]); });
Q('l03', mk.long({ stem: r`At Eden Gardens in Kolkata, a club sells "gold" and "silver" tickets for a match. On day 1 it sold $200$ gold and $500$ silver tickets for ₹$2{,}00{,}000$. On day 2 it sold $300$ gold and $400$ silver tickets for ₹$2{,}30{,}000$.

(a) Form a pair of linear equations.
(b) Find the price of each kind of ticket.
(c) On day 3 it sold $250$ gold and $600$ silver tickets. Find the collection.`, model: r`(a) Let a gold ticket cost ₹$g$ and a silver ticket ₹$s$. $200g + 500s = 200000 \Rightarrow 2g + 5s = 2000$; $300g + 400s = 230000 \Rightarrow 3g + 4s = 2300$.

(b) Multiply by $3$ and $2$: $6g + 15s = 6000$ and $6g + 8s = 4600$. Subtract: $7s = 1400$, $s = 200$. Then $2g = 2000 - 1000$, $g = 500$. Gold ₹$500$, silver ₹$200$.

(c) $250 \times 500 + 600 \times 200 = 125000 + 120000 = $ ₹$2{,}45{,}000$.`, sol: r`Check: $200 \times 500 + 500 \times 200 = 200000$ ✓; $300 \times 500 + 400 \times 200 = 230000$ ✓.`, scheme: [['Two equations (simplified)', 1], ['Elimination step', 1], ['Silver ₹200', 1], ['Gold ₹500', 1], ['Day 3: ₹2,45,000', 1]], d: 3, c: 'application', t: [5], time: 600 }), (C) => { const [g, s] = sol(2, 5, 2000, 3, 4, 2300); C.model([g, s, 250 * g + 600 * s, 7, 1400]); });
Q('l04', mk.long({ stem: r`Consider the pair $kx + 2y = 5$ and $3x + y = 1$.

(a) Find the value of $k$ for which the pair has no solution, and describe the graphs for this $k$.
(b) Show that there is **no** value of $k$ for which the pair has infinitely many solutions.
(c) Solve the pair when $k = 4$.`, model: r`(a) No solution needs $\dfrac k3 = \dfrac21 \ne \dfrac51$. So $k = 6$ (and indeed $2 \ne 5$). For $k = 6$ the lines $6x + 2y = 5$ and $3x + y = 1$ are **parallel**.

(b) Infinitely many solutions would need all three ratios equal, in particular $\dfrac{b_1}{b_2}$ and $\dfrac{c_1}{c_2}$. These are $\dfrac21$ and $\dfrac51$, and $\dfrac21 \ne \dfrac51$ whatever $k$ is. So no $k$ works.

(c) $k = 4$: $4x + 2y = 5$ and $3x + y = 1$. Double the second: $6x + 2y = 2$. Subtract the first: $2x = -3$, $x = -1.5$. Then $y = 1 - 3(-1.5) = 5.5$.

Check: $4(-1.5) + 2(5.5) = -6 + 11 = 5$ ✓.`, sol: 'The ratio of the y-coefficients and constants is fixed by the second equation; only k can vary.', scheme: [['Condition and k = 6', 1], ['Parallel lines for k = 6', 1], ['(b) 2/1 ≠ 5/1 for every k', 1], ['(c) x = −1.5', 1], ['(c) y = 5.5 with check', 1]], d: 4, c: 'analysis', t: [2, 4], time: 660 }), (C) => { C.assert(kind(6, 2, 5, 3, 1, 1) === 'none' && [-10, -3, 0, 3, 6, 10].every((k) => kind(k, 2, 5, 3, 1, 1) !== 'infinite'), 'k = 6, never infinite'); const p = sol(4, 2, 5, 3, 1, 1); C.assert(eqPt(p, [-1.5, 5.5]), `${p}`); C.model([6, -1.5, 5.5]); });
Q('l05', mk.long({ stem: r`Reema's purse has only ₹$2$ and ₹$5$ coins: $30$ coins worth ₹$96$. She lets $x$ = number of ₹$2$ coins and $y$ = number of ₹$5$ coins, and writes $x + y = 30$ and $5x + 2y = 96$. She gets $x = 12$, $y = 18$ and concludes that she has twelve ₹$2$ coins.

(a) Check her answer against the story.
(b) Identify her mistake.
(c) Write the correct equations and solve them.
(d) Explain why her wrong system still gave whole-number answers.`, model: r`(a) Twelve ₹$2$ coins and eighteen ₹$5$ coins are worth $24 + 90 = $ ₹$114 \ne$ ₹$96$, so her answer is wrong.

(b) The value equation is wrong: $x$ coins of ₹$2$ are worth $2x$, not $5x$. She swapped the values.

(c) $x + y = 30$ and $2x + 5y = 96$. Substitute $x = 30 - y$: $2(30 - y) + 5y = 96 \Rightarrow 60 + 3y = 96 \Rightarrow 3y = 36 \Rightarrow y = 12$, $x = 18$. She has eighteen ₹$2$ coins and twelve ₹$5$ coins. Check: $36 + 60 = 96$ ✓.

(d) Her system is the correct one with the roles of $x$ and $y$ exchanged, so it has the same numbers in swapped positions: it solved a real story, just not hers. Always check the answer in the **original words**.`, sol: 'Translate each sentence with the meaning of each variable written down.', scheme: [['(a) value ₹114 ≠ ₹96', 1], ['(b) value equation should be 2x + 5y', 1], ['(c) correct pair', 1], ['(c) x = 18, y = 12 with check', 1], ['(d) explanation: roles of x and y swapped', 1]], d: 5, c: 'evaluation', t: [5], time: 660 }), (C) => { const [x0, y0] = sol(1, 1, 30, 5, 2, 96); C.assert(x0 === 12 && y0 === 18 && 2 * x0 + 5 * y0 === 114, 'her answer'); const [x, y] = sol(1, 1, 30, 2, 5, 96); C.model([114, x, y, 36]); });
Q('l06', mk.long({ stem: r`The graph shows two lines.

(a) Write the equation of each line.
(b) Solve the pair algebraically and mark the solution on the graph.
(c) Write the equation of a line parallel to line 1 through $(0, 6)$, and state how many solutions it has with line 1.
(d) Write an equation, different from line 2's, that has infinitely many solutions in common with line 2.`, assets: [qGraphL6], model: r`(a) Line 1 through $(0, 4)$ and $(4, 0)$: $x + y = 4$. Line 2 through $(0, -2)$ and $(2, 0)$: $x - y = 2$.

(b) Adding: $2x = 6$, $x = 3$, $y = 1$. The lines cross at $(3, 1)$.

(c) $x + y = 6$. Ratios $\dfrac11 = \dfrac11 \ne \dfrac46$: parallel to line 1, so **no** solution in common.

(d) Any non-zero multiple of line 2, e.g. $2x - 2y = 4$ (all ratios equal: coincident).`, sol: 'Intercept form: a line through (p, 0) and (0, q) has every point satisfying x/p + y/q = 1.', scheme: [['Line 1: x + y = 4', 1], ['Line 2: x − y = 2', 1], ['Solution (3, 1)', 1], ['Parallel line x + y = 6, no solution', 1], ['Coincident line, e.g. 2x − 2y = 4', 1]], d: 4, c: 'analysis', t: [1, 2], time: 660 }), (C) => { C.assert(eqPt(sol(1, 1, 4, 1, -1, 2), [3, 1]) && kind(1, 1, 6, 1, 1, 4) === 'none' && kind(2, -2, 4, 1, -1, 2) === 'infinite', 'parts'); C.model(['x + y = 4', 'x - y = 2', '(3, 1)', 'x + y = 6', '2x - 2y = 4']); });

// =============================================================== Case-based
caseQ('c01', {
  passage: r`At the Dussehra fair in Mysuru, Ravi took $3$ giant-wheel rides and $2$ toy-train rides and paid ₹$240$. His cousin Sita took $2$ giant-wheel rides and $3$ toy-train rides and paid ₹$210$. Let one giant-wheel ride cost ₹$w$ and one toy-train ride ₹$t$.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $3w + 2t = 240$, $2w + 3t = 210$. (b) $w + t = 90$. (c) (i) $w = 60$, $t = 30$. Or (ii) ₹$390$.`,
  sol: r`(a) Ravi: $3w + 2t = 240$; Sita: $2w + 3t = 210$. (b) Adding: $5w + 5t = 450$, so $w + t = 90$. (c) (i) Subtracting: $w - t = 30$; with $w + t = 90$: $w = 60$, $t = 30$. (ii) $4 \times 60 + 5 \times 30 = 390$.`,
  children: [
    child('a', mk.mcq({ stem: 'The pair of equations for the story is', opts: [r`$3w + 2t = 240,\ 2w + 3t = 210$`, r`$3w + 2t = 210,\ 2w + 3t = 240$`, r`$2w + 3t = 240,\ 3w + 2t = 210$`, r`$5w + 5t = 450,\ w - t = 30$`], key: 'a', sol: 'Ravi: 3 wheel + 2 train = 240; Sita: 2 wheel + 3 train = 210. Option (d) is true but derived, not the pair read from the story.', d: 1, c: 'understanding', t: [5], time: 60 })),
    child('b', mk.num({ stem: 'Without finding w and t separately, find the cost (in ₹) of one ride on each, i.e. w + t.', value: 90, unit: '₹', sol: r`Add the equations: $5w + 5t = 450$, so $w + t = 90$.`, scheme: [['90', 1]], d: 2, c: 'application', t: [4], time: 60 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the cost of one giant-wheel ride and of one toy-train ride.', model: r`Subtract the equations: $w - t = 30$. With $w + t = 90$: $2w = 120$, $w = 60$; $t = 30$. Giant wheel ₹$60$, toy train ₹$30$.`, sol: 'Use the sum and difference.', scheme: [['w − t = 30', 1], ['₹60 and ₹30', 1]], d: 2, c: 'application', t: [4], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** How much would 4 giant-wheel rides and 5 toy-train rides cost? Show your working.', model: r`From the equations, $w = 60$ and $t = 30$. Cost $= 4 \times 60 + 5 \times 30 = 240 + 150 = $ ₹$390$.`, sol: 'Solve first, then substitute.', scheme: [['w = 60, t = 30', 1], ['₹390', 1]], d: 3, c: 'application', t: [5], time: 150 }),
    ]),
  ],
}, (C) => { const [w, t] = sol(3, 2, 240, 2, 3, 210); C.child('a').key('a'); C.child('b').val(w + t); C.child('c').model([w, t, 30]); C.child('cii').model([4 * w + 5 * t]); });

caseQ('c02', {
  passage: r`Two courier companies in Bhubaneswar charge for parcel delivery as follows. Company A: a fixed ₹$40$ plus ₹$10$ per km. Company B: a fixed ₹$20$ plus ₹$15$ per km. For a distance of $x$ km the charge is ₹$y$, so A: $y = 40 + 10x$ and B: $y = 20 + 15x$. The graph shows both lines.`,
  assets: [qDelivery], d: 3, c: 'analysis',
  model: r`(a) Option (c): the distance at which both charge the same. (b) $4$ km. (c) (i) For $10$ km, A charges ₹$140$ and B ₹$170$, so A is cheaper by ₹$30$. Or (ii) The lines would be parallel ($y = 40 + 10x$ and $y = 20 + 10x$): no solution, the charges are never equal; A always costs ₹$20$ more.`,
  sol: r`(b) $40 + 10x = 20 + 15x \Rightarrow 5x = 20 \Rightarrow x = 4$ (charge ₹$80$). (c) (i) $40 + 100 = 140$, $20 + 150 = 170$. (ii) Rewritten: $10x - y = -40$ and $10x - y = -20$; ratios $\dfrac{10}{10} = \dfrac{-1}{-1} \ne \dfrac{-40}{-20}$.`,
  children: [
    child('a', mk.mcq({ stem: 'The point where the two lines cross represents', opts: ['the fixed charge of each company', 'the charge per km of each company', 'the distance at which both companies charge the same', 'the distance at which both charges are zero'], key: 'c', sol: 'At the crossing point both equations hold with the same x and y: same distance, same charge.', d: 1, c: 'understanding', t: [1], time: 45 })),
    child('b', mk.num({ stem: 'Find the distance (in km) for which the two companies charge the same.', value: 4, unit: 'km', sol: r`$40 + 10x = 20 + 15x \Rightarrow 5x = 20 \Rightarrow x = 4$ km (both charge ₹$80$).`, scheme: [['4 km', 1]], d: 2, c: 'application', t: [3], time: 75 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Which company is cheaper for a 10 km delivery, and by how much?', model: r`A: $40 + 10 \times 10 = $ ₹$140$. B: $20 + 15 \times 10 = $ ₹$170$. Company A is cheaper by ₹$30$.`, sol: 'Substitute x = 10 into both.', scheme: [['₹140 and ₹170', 1], ['A cheaper by ₹30', 1]], d: 2, c: 'application', t: [5], time: 90 }), [
      mk.short({ marks: 2, stem: '**(ii)** If company B lowers its rate to ₹10 per km (keeping its fixed charge), will the two charges ever be equal? Use the condition for a pair of linear equations.', model: r`B becomes $y = 20 + 10x$. As $10x - y = -40$ and $10x - y = -20$: $\dfrac{a_1}{a_2} = \dfrac{b_1}{b_2} = 1 \ne \dfrac{c_1}{c_2} = 2$. The lines are parallel: no solution, so the charges are never equal (A is always ₹$20$ more).`, sol: 'Ratio test on the rewritten equations.', scheme: [['Ratio test', 1], ['Parallel, never equal', 1]], d: 4, c: 'analysis', t: [2], time: 150 }),
    ]),
  ],
}, (C) => { const [x, y] = sol(-10, 1, 40, -15, 1, 20); C.assert(x === 4 && y === 80, 'crossing'); C.child('a').key('c'); C.child('b').val(x); C.child('c').model([140, 170, 30]); C.child('cii').assert(kind(10, -1, -40, 10, -1, -20) === 'none', 'parallel'); C.child('cii').model(['parallel']); });

caseQ('c03', {
  passage: r`In a maths quiz in Shillong, teams are given three pairs of equations and asked to decide, without drawing, how many solutions each pair has.

| Pair | Equations |
|---|---|
| P | $2x + 3y = 5$, $4x + 6y = 10$ |
| Q | $x - y = 3$, $2x - 2y = 7$ |
| R | $3x + y = 4$, $x - 2y = -1$ |`,
  d: 3, c: 'analysis',
  model: r`(a) Option (c): pair R. (b) Infinitely many. (c) (i) $x = 1$, $y = 1$. Or (ii) For example, change $2x - 2y = 7$ to $2x - 3y = 7$: now $\dfrac21 \ne \dfrac{-3}{-1}$, so the pair has a unique solution and is consistent.`,
  sol: r`(a) P: all ratios $\dfrac12$ (coincident). Q: $\dfrac12 = \dfrac12 \ne \dfrac37$ (parallel). R: $\dfrac31 \ne \dfrac{1}{-2}$ (unique). (b) Coincident lines. (c) (i) From the second, $x = 2y - 1$; $3(2y - 1) + y = 4 \Rightarrow 7y = 7$, $y = 1$, $x = 1$. (ii) Any change that makes $\dfrac{a_1}{a_2} \ne \dfrac{b_1}{b_2}$.`,
  children: [
    child('a', mk.mcq({ stem: 'Which pair has a unique solution?', opts: ['P', 'Q', 'R', 'none of them'], key: 'c', sol: r`Only R has $\dfrac{a_1}{a_2} \ne \dfrac{b_1}{b_2}$ ($3 \ne -\dfrac12$).`, d: 2, c: 'analysis', t: [2], time: 75 })),
    child('b', mk.fill({ stem: 'Pair P has ___ solutions.', acc: [['infinitely many', 'infinite', 'infinitely']], sol: r`$\dfrac24 = \dfrac36 = \dfrac{5}{10}$: the lines coincide.`, d: 2, c: 'understanding', t: [2], time: 45 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Solve pair R.', model: r`From $x - 2y = -1$, $x = 2y - 1$. Then $3(2y - 1) + y = 4 \Rightarrow 7y = 7 \Rightarrow y = 1$, $x = 1$. Check: $3 + 1 = 4$ ✓.`, sol: 'Substitution.', scheme: [['y = 1', 1], ['x = 1 with check', 1]], d: 2, c: 'application', t: [3], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** Change one coefficient in pair Q so that it has exactly one solution. Justify using ratios.', model: r`For example, change $2x - 2y = 7$ to $2x - 3y = 7$. Then $\dfrac{a_1}{a_2} = \dfrac12$ and $\dfrac{b_1}{b_2} = \dfrac{-1}{-3} = \dfrac13$, which are unequal, so the lines intersect: exactly one solution. (Any change making $\dfrac{a_1}{a_2} \ne \dfrac{b_1}{b_2}$ is correct.)`, sol: 'Break the equality of the first two ratios.', scheme: [['A valid change', 1], ['Ratio justification', 1]], d: 4, c: 'analysis', t: [2], time: 150 }),
    ]),
  ],
}, (C) => { const kinds = [kind(2, 3, 5, 4, 6, 10), kind(1, -1, 3, 2, -2, 7), kind(3, 1, 4, 1, -2, -1)]; C.assert(kinds.join() === 'infinite,none,unique', kinds.join()); C.child('a').which(['P', 'Q', 'R', 'none'], ['P', 'Q', 'R'][kinds.indexOf('unique')] ?? 'none'); C.child('b').blank('infinitely many'); C.child('c').assert(eqPt(sol(3, 1, 4, 1, -2, -1), [1, 1]), 'R'); C.child('cii').assert(kind(1, -1, 3, 2, -3, 7) === 'unique', 'changed Q'); C.child('c').model([1]); });

caseQ('c04', {
  passage: 'In Lucknow, Dadi (the grandmother) and her grandson Aman were asked their ages for a family quiz. Dadi said: "The sum of our ages is 80 years. Five years ago, I was nine times as old as Aman was then."',
  d: 3, c: 'application',
  model: r`(a) Option (b): $g + a = 80$ and $g - 9a = -40$. (b) Aman is $12$ years old. (c) (i) In $2$ years ($70 = 5 \times 14$). Or (ii) In $10$ years.`,
  sol: r`(a) $g - 5 = 9(a - 5) \Rightarrow g - 9a = -40$. (b) Subtract from $g + a = 80$: $10a = 120$, $a = 12$, $g = 68$. (c) (i) $68 + n = 5(12 + n) \Rightarrow 4n = 8 \Rightarrow n = 2$. (ii) $80 + 2n = 100 \Rightarrow n = 10$.`,
  children: [
    child('a', mk.mcq({ stem: "With Dadi's age g and Aman's age a, the pair of equations is", opts: [r`$g + a = 80,\ g = 9a$`, r`$g + a = 80,\ g - 9a = -40$`, r`$g + a = 80,\ g - 9a = 40$`, r`$g - a = 80,\ g - 9a = -40$`], key: 'b', sol: r`$g - 5 = 9(a - 5) = 9a - 45$, so $g - 9a = -40$. Option (a) ignores "five years ago"; (c) has a sign slip.`, d: 2, c: 'understanding', t: [5], time: 75 })),
    child('b', mk.num({ stem: "Find Aman's present age in years.", value: 12, unit: 'years', sol: r`$(g + a) - (g - 9a) = 80 - (-40) \Rightarrow 10a = 120 \Rightarrow a = 12$ (Dadi is $68$). Check: five years ago $63 = 9 \times 7$ ✓.`, scheme: [['12 years', 1]], d: 2, c: 'application', t: [5], time: 90 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** After how many years will Dadi be five times as old as Aman?', model: r`$68 + n = 5(12 + n) \Rightarrow 68 + n = 60 + 5n \Rightarrow 4n = 8 \Rightarrow n = 2$. In $2$ years (Dadi $70$, Aman $14$; $70 = 5 \times 14$ ✓).`, sol: 'Add the same n to both ages.', scheme: [['Equation 68 + n = 5(12 + n)', 1], ['n = 2', 1]], d: 3, c: 'application', t: [5], time: 150 }), [
      mk.short({ marks: 2, stem: '**(ii)** After how many years will the sum of their ages be 100 years? Explain why the answer is not 20.', model: r`Each year **both** ages increase by $1$, so the sum grows by $2$ per year: $80 + 2n = 100 \Rightarrow n = 10$ years. Answering $20$ would wrongly add $1$ per year to the sum.`, sol: 'The sum grows by 2 each year.', scheme: [['80 + 2n = 100', 1], ['10 years, with the reason', 1]], d: 3, c: 'analysis', t: [5], time: 120 }),
    ]),
  ],
}, (C) => { const [g, a] = sol(1, 1, 80, 1, -9, -40); C.assert(g === 68 && a === 12 && g - 5 === 9 * (a - 5), 'ages'); C.child('a').key('b'); C.child('b').val(a); C.child('c').model([2, 70, 14]); C.child('cii').model([10]); });

caseQ('c05', {
  passage: r`Three friends in Chandigarh solve the pair $3x + 2y = 12$ and $5x - 2y = 4$ in different ways. Aisha adds the equations. Babu writes $y = \dfrac{12 - 3x}{2}$ and substitutes it into the second equation. Chetan multiplies the first equation by $5$ and the second by $3$, then subtracts to eliminate $x$.`,
  d: 3, c: 'evaluation',
  model: r`(a) Option (a): adding eliminates $y$ at once, because the $y$-coefficients are $+2$ and $-2$. (b) $y = 3$. (c) (i) $(2, 3)$ satisfies both equations; it is where the two lines intersect. Or (ii) Chetan's method works: $15x + 10y = 60$ and $15x - 6y = 12$; subtracting gives $16y = 48$, $y = 3$, the same answer — but it needs more arithmetic than Aisha's.`,
  sol: r`(a) $8x = 16$, $x = 2$ in one step. (b) $3(2) + 2y = 12 \Rightarrow y = 3$. (c) (i) $6 + 6 = 12$ ✓, $10 - 6 = 4$ ✓. (ii) as in the model answer.`,
  children: [
    child('a', mk.mcq({ stem: 'Which method needs the least work for this pair, and why?', opts: ["Aisha's: the y-coefficients are already opposites", "Babu's: substitution is always quickest", "Chetan's: x must always be eliminated first", 'All need exactly the same work'], key: 'a', sol: r`The $y$-terms $+2y$ and $-2y$ cancel on adding: $8x = 16$ immediately.`, d: 2, c: 'evaluation', t: [4], time: 60 })),
    child('b', mk.num({ stem: 'Find the value of y.', value: 3, sol: r`Adding: $8x = 16$, $x = 2$; then $6 + 2y = 12$, $y = 3$.`, scheme: [['3', 1]], d: 1, c: 'understanding', t: [4], time: 60 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Verify the solution and state what it means for the graphs of the two equations.', model: r`$x = 2$, $y = 3$: $3(2) + 2(3) = 12$ ✓ and $5(2) - 2(3) = 4$ ✓. The graphs are two lines that intersect at the single point $(2, 3)$.`, sol: 'Substitute into both equations.', scheme: [['Both checks', 1], ['Lines intersect at (2, 3)', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), [
      mk.short({ marks: 2, stem: "**(ii)** Does Chetan's method work? Carry it out and compare it with Aisha's.", model: r`Yes. $5 \times$ first: $15x + 10y = 60$; $3 \times$ second: $15x - 6y = 12$. Subtract: $16y = 48$, $y = 3$, then $x = 2$. Same answer, but with larger numbers and an extra step; Aisha's addition is quicker here.`, sol: 'Any valid elimination gives the same unique solution.', scheme: [['16y = 48, y = 3', 1], ['Comparison: valid but longer', 1]], d: 3, c: 'evaluation', t: [4], time: 150 }),
    ]),
  ],
}, (C) => { const p = sol(3, 2, 12, 5, -2, 4); C.assert(eqPt(p, [2, 3]), 'sol'); C.child('a').key('a'); C.child('b').val(p[1]); C.child('c').model(['(2, 3)']); C.child('cii').model([60, 12, 16, 48]); });
